import{z as B,x as A,o as l,c as p,q as o,j as n,D as e,d as E,s as r,S as s,b as t}from"./chunks/framework.C8m1ZpeB.js";const C=JSON.parse('{"title":"策略梯度定理","description":"","frontmatter":{"title":"策略梯度定理","date":"2026-09-18T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/policy-gradient-theorem.md","filePath":"llm/policy-gradient-theorem.md","lastUpdated":1791063341000}'),_={name:"llm/policy-gradient-theorem.md"};function h(m,a,d,u,g,b){const i=A("Mermaid");return l(),p("div",null,[a[2]||(a[2]=o('<h1 id="策略梯度定理" tabindex="-1">策略梯度定理 <a class="header-anchor" href="#策略梯度定理" aria-label="Permalink to &quot;策略梯度定理&quot;">​</a></h1><div class="epigraph"><p>值方法先学「局面值多少」再挑动作；策略梯度把方向倒过来——直接对「动作怎么挑」求导，让环境的好报指出该抬高谁的概率。</p><footer>—— 据 Sutton, McAllester, Singh &amp; Mansour, 2000；Sutton &amp; Barto, Reinforcement Learning, 2018 第 13 章整理</footer></div><p><a href="/llm/gridworld-lab-lesson">上一课</a>在网格世界上跑完了 MC、TD 与 Q-learning：收敛快慢、步长敏感、探索率的作用都成了能复现的曲线。它们共享一个前提——先估值，再由 \\(\\arg\\max_a Q(s,a)\\) 间接读出策略。语言生成把这个前提压塌：状态是 prompt 加前缀，动作是十几万个 token 之一，每步做词表上的 argmax 既贵又不可导；而语言模型本身就是 \\(\\pi_\\theta(y_t\\mid x,y_{\\lt t})\\) 这台现成的随机策略。本课写策略梯度定理：\\(\\nabla_\\theta J\\) 的得分函数形式，它对值函数方法的对照，以及为什么整条推导不需要对状态转移求导。本单元后课默认已读完本课。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>把轨迹 \\(\\tau=(s_0,a_0,r_1,\\ldots,s_T)\\) 的期望回报 \\(J(\\theta)=\\mathbb{E}_{\\tau\\sim\\pi_\\theta}[R(\\tau)]\\) 当目标，想直接求 \\(\\nabla_\\theta J\\)。麻烦在轨迹分布的每一项都被 \\(\\theta\\) 牵着：策略改了，动作分布变；动作变了，访问哪些状态也变。按复合函数直接链式展开，会撞上 \\(\\nabla_\\theta P(s&#39;\\mid s,a)\\)——无模型设定下没有转移模型，这条路走不通。值方法绕开它的方式是换成贝尔曼方程逐点估计；策略梯度要的是另一条路：只用「环境会发分、策略能采样」这两个事实，给出无偏梯度。</p><p>值方法的间接性还有两处硬伤。其一，\\(\\arg\\max\\) 是映射不是光滑函数，对函数逼近误差极敏感；其二，最优策略若需要随机化——或者你手里本来就有一台随机策略模型——\\(\\arg\\max\\) 根本给不出它。</p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>绕开的核心是 likelihood-ratio 恒等式：\\(\\nabla_\\theta\\pi_\\theta(\\tau)=\\pi_\\theta(\\tau)\\,\\nabla_\\theta\\log\\pi_\\theta(\\tau)\\)。轨迹对数概率拆成三段——初始分布、各步转移、各步动作；前两段不含 \\(\\theta\\)，求导后严格为零，只剩</p><p><span class="marginnote">这个恒等式就是「先取对数再求导」：\\(\\log\\) 把乘积变连加，求导时 \\(\\nabla\\pi\\) 归约成 \\(\\pi\\,\\nabla\\log\\pi\\)。它不引入任何近似——所以本课之后的所有结论都是严格等式，不是「大概成立」。</span></p> \\[\\nabla_\\theta J(\\theta)=\\mathbb{E}_{\\tau\\sim\\pi_\\theta}\\Bigl[\\sum_{t}\\nabla_\\theta\\log\\pi_\\theta(a_t\\mid s_t)\\,G_t\\Bigr], \\]<p>其中 \\(\\nabla_\\theta\\log\\pi_\\theta(a\\mid s)\\) 叫得分函数（score function），\\(G_t\\) 是从 \\(t\\) 起的折扣回报。这就是策略梯度定理：梯度只是得分与回报乘积的期望，转移核一次也没出现。不是被近似掉，而是恒等式里根本轮不到它。这一下把「需要环境模型」降成「需要能从环境采样」：跑回合、记对数概率、记回报，梯度就能逐项累积。</p><p><span class="marginnote">得分函数可以读成「往哪个方向调参数，会让动作 \\(a\\) 在状态 \\(s\\) 下更常被抽到」；乘上 \\(G_t\\) 就是按这一回合的收益成比例地抬高（或压低）这个动作的概率——赚得多多抬高，亏了反向压低。</span></p>',12)),(l(),n(s,null,{default:e(()=>[r(i,{id:"mermaid-32",class:"mermaid",graph:"flowchart%20TD%0A%20%20TAU%5B%22%E4%BB%8E%E5%BD%93%E5%89%8D%E7%AD%96%E7%95%A5%E9%87%87%E6%A0%B7%E8%BD%A8%E8%BF%B9%22%5D%20--%3E%20SCORE%5B%22%E8%AE%B0%E5%90%84%E6%AD%A5%E5%BE%97%E5%88%86%20grad%20log%20pi(at%2C%20st)%22%5D%0A%20%20TAU%20--%3E%20RET%5B%22%E8%AE%B0%E5%90%84%E6%AD%A5%E5%9B%9E%E6%8A%A5%20Gt%22%5D%0A%20%20SCORE%20--%3E%20W%5B%22%E9%80%90%E9%A1%B9%E7%9B%B8%E4%B9%98%E5%86%8D%E6%B1%82%E5%92%8C%22%5D%0A%20%20RET%20--%3E%20W%0A%20%20W%20--%3E%20G%5B%22%E6%97%A0%E5%81%8F%E9%9A%8F%E6%9C%BA%E6%A2%AF%E5%BA%A6%22%5D%0A%20%20G%20--%3E%20UP%5B%22%E6%9B%B4%E6%96%B0%E5%8F%82%E6%95%B0%22%5D%0A%20%20UP%20--%3E%20TAU%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[E(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=t("h2",{id:"机制",tabindex:"-1"},[E("机制 "),t("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=t("p",null,"定理为什么成立值得再看一眼：对任意状态，\\(\\sum_a\\nabla_\\theta\\pi_\\theta(a\\mid s)=\\nabla_\\theta 1=0\\)，得分函数在策略自身分布下期望为零。这个零均值是整族方法的支点——任何只依赖状态的量乘上得分，期望都不变，下一课的基线定理就是它。与值方法对照：值路线把全部难度压在估计 \\(Q\\) 上，策略是免费的副产品；策略梯度把难度压在方差上，策略本身可导。LLM 选后者有具体理由：token 采样是离散动作，重参数化的 pathwise 导数不存在，得分函数形式是唯一通路；softmax 策略的得分还有闭式 \\(\\nabla_\\theta\\log\\pi_\\theta(a\\mid s)=\\phi(s,a)-\\mathbb{E}_{a'\\sim\\pi_\\theta}[\\phi(s,a')]\\)，动作特征减去其在策略下的均值。",-1)),a[5]||(a[5]=t("p",null,[t("span",{class:"marginnote"},"「避免状态导数」的准确含义：\\(\\nabla\\log\\pi_\\theta(\\tau)\\) 里初始分布与转移项严格为零，期望的支撑怎么随 \\(\\theta\\) 移动都不用管——这是恒等式，不是近似。若推导里出现了对 \\(P(s'\\mid s,a)\\) 的导数，那已经不是这条定理。")],-1)),a[6]||(a[6]=t("p",null,"「转移核为什么一次也没出现」逐段看轨迹对数概率的拆解：",-1)),(l(),n(s,null,{default:e(()=>[r(i,{id:"mermaid-45",class:"mermaid",graph:"flowchart%20TD%0A%20%20LT%5B%22log%20pi_theta(tau)%20%E6%8B%86%E6%88%90%E4%B8%89%E6%AE%B5%22%5D%20--%3E%20L0%5B%22%E5%88%9D%E5%A7%8B%E5%88%86%E5%B8%83%E9%A1%B9%20log%20rho_0(s_0)%22%5D%0A%20%20LT%20--%3E%20L1%5B%22%E8%BD%AC%E7%A7%BB%E9%A1%B9%20log%20P(s_t%2B1%20%7C%20s_t%2C%20a_t)%22%5D%0A%20%20LT%20--%3E%20L2%5B%22%E5%8A%A8%E4%BD%9C%E9%A1%B9%20log%20pi_theta(a_t%20%7C%20s_t)%22%5D%0A%20%20L0%20--%3E%20Z0%5B%22%E4%B8%8D%E5%90%AB%20theta%EF%BC%9A%E6%B1%82%E5%AF%BC%E4%B8%A5%E6%A0%BC%E4%B8%BA%200%22%5D%0A%20%20L1%20--%3E%20Z1%5B%22%E4%B8%8D%E5%90%AB%20theta%EF%BC%9A%E6%B1%82%E5%AF%BC%E4%B8%A5%E6%A0%BC%E4%B8%BA%200%22%5D%0A%20%20L2%20--%3E%20K%5B%22%E5%90%AB%20theta%EF%BC%9A%E5%8F%AA%E5%89%A9%E5%BE%97%E5%88%86%E5%87%BD%E6%95%B0%22%5D%0A%20%20K%20--%3E%20G%5B%22%E6%A2%AF%E5%BA%A6%20%3D%20E%5B%E5%BE%97%E5%88%86%20x%20%E5%9B%9E%E6%8A%A5%5D%EF%BC%8C%E6%97%A0%E9%9C%80%E7%8E%AF%E5%A2%83%E6%A8%A1%E5%9E%8B%22%5D%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[E(" Loading... ",-1)])]),_:1})),a[7]||(a[7]=o('<h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>定理给的是<strong>当前</strong> \\(\\theta\\) 处的无偏梯度：每更新一步，采样分布就变，旧轨迹的梯度不再对准新策略——复用旧数据必须加重要性权重，那是本课程后面专课处理比率方差的题目。它也不回答步长：参数空间一小步可以是分布上的一大步，本单元最后一课才处理。最直接的麻烦是方差：\\(G_t\\) 的波动原样乘进得分，长回合下估计量吵得没法用——这正是下一课 REINFORCE 要面对的现实。</p><p><span class="marginnote">初学者容易以为「无偏」就等于「稳」；无偏只保证平均方向对，单次估计仍可能大起大落。方差大时每步更新都像掷骰子——这正是后来要加基线、控比率、做信任域的动因。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>策略梯度定理：\\(\\nabla_\\theta J=\\mathbb{E}_{\\tau}[\\sum_t\\nabla_\\theta\\log\\pi_\\theta(a_t\\mid s_t)G_t]\\)，得分函数形式。</li><li>转移核不出现在梯度里：likelihood-ratio 恒等式使状态导数严格为零，无模型也能算。</li><li>对照值方法：不用 \\(\\arg\\max\\)、支持随机策略；离散动作下得分函数是唯一可导通路。</li><li>期望在当前策略下取，数据必须 on-policy；步长问题留给信任域。</li><li>出处：Sutton, McAllester, Singh &amp; Mansour, 2000；Williams, 1992；Sutton &amp; Barto, <em>Reinforcement Learning</em>, 2018，第 13 章。</li></ul>',5))])}const c=B(_,[["render",h]]);export{C as __pageData,c as default};
